do $$
declare aid uuid:=gen_random_uuid();bid uuid:=gen_random_uuid();doc jsonb;first_date timestamptz;result jsonb;
begin
 doc:='{"slug":"publication-check-a","title":"Visible uno","summary":"Texto publico","author":"Equipo","category":"naturaleza","cover":"/blog-media/publication-cover","coverAlt":"Bosque","bodyImage":{"src":"/blog-media/publication-body","alt":"Sendero"},"metaDescription":"SEO visible uno","document":{"version":1,"blocks":[]}}';
 perform public.blog_admin('create',jsonb_build_object('id',aid,'document',doc),null,true);
 perform public.blog_admin('create',jsonb_build_object('id',bid,'document',doc||'{"slug":"publication-check-b"}'),null,true);
 perform public.blog_admin('publish',jsonb_build_object('id',aid,'version',1),null,true);
 perform public.blog_admin('publish',jsonb_build_object('id',bid,'version',1),null,true);
 select published_at into first_date from public.blog_publications where id=aid;
 perform public.blog_admin('feature',jsonb_build_object('id',aid,'version',1),null,true);
 if (select count(*) from public.blog_publications where featured)<>1 then raise exception 'multiple features'; end if;
 perform public.blog_admin('move',jsonb_build_object('id',bid,'version',1,'position',0),null,true);
 if exists(select 1 from public.blog_publications p join private.blog_articles a on p.id=a.id where p.id in (aid,bid) and p.version<>a.published_version) then raise exception 'order version mismatch'; end if;
 perform public.blog_admin('save',jsonb_build_object('id',bid,'version',2,'document',doc),null,true);
 if public.blog_admin('publish',jsonb_build_object('id',bid,'version',3),null,true)->>'status'<>'conflict' then raise exception 'slug collision accepted'; end if;
 perform public.blog_admin('save',jsonb_build_object('id',aid,'version',2,'document',doc||'{"title":"Privado dos","metaDescription":"SEO privado dos"}'),null,true);
 result:=public.blog_read('publication-check-a');
 if result->'article'->>'title'<>'Visible uno' or result->'article'->>'metaDescription'<>'SEO visible uno' then raise exception 'draft changed public content or SEO'; end if;
 perform public.blog_admin('publish',jsonb_build_object('id',aid,'version',3),null,true);
 result:=public.blog_read('publication-check-a');
 if result->'article'->>'title'<>'Privado dos' or result->'article'->>'metaDescription'<>'SEO privado dos' then raise exception 'publication snapshot split'; end if;
 if (select published_at from public.blog_publications where id=aid)<>first_date then raise exception 'first publication date changed'; end if;
 perform public.blog_admin('save',jsonb_build_object('id',aid,'version',3,'document',doc||'{"title":"Otro borrador"}'),null,true);
 perform public.blog_admin('restore',jsonb_build_object('id',aid,'version',4,'restore_version',1),null,true);
 if public.blog_read('publication-check-a')->'article'->>'title'<>'Privado dos' then raise exception 'restore published automatically'; end if;
 if (select count(*) from private.blog_revisions where article_id=aid)<>5 then raise exception 'revision overwritten'; end if;
 perform public.blog_admin('publish',jsonb_build_object('id',aid,'version',5),null,true);
 perform public.blog_admin('save',jsonb_build_object('id',aid,'version',5,'document',doc||'{"slug":"publication-check-renamed"}'),null,true);
 perform public.blog_admin('publish',jsonb_build_object('id',aid,'version',6),null,true);
 if public.blog_read('publication-check-a')->>'status'<>'redirect' or public.blog_read('publication-check-a')->>'slug'<>'publication-check-renamed' then raise exception 'redirect broken'; end if;
 perform public.blog_admin('archive',jsonb_build_object('id',aid,'version',6),null,true);
 if public.blog_read('publication-check-renamed')->>'status'<>'not_found' then raise exception 'archive direct access'; end if;
 if exists(select 1 from jsonb_array_elements(public.blog_sitemap()->'items') e where e->>'slug'='publication-check-renamed') then raise exception 'archive sitemap'; end if;
 if exists(select 1 from jsonb_array_elements(public.blog_related('publication-check-b')->'items') e where e->>'slug'='publication-check-renamed') then raise exception 'archive related'; end if;
 if not (public.blog_media_visible('/blog-media/publication-body')->>'visible')::boolean then raise exception 'shared published image hidden'; end if;
 perform public.blog_admin('archive',jsonb_build_object('id',bid,'version',3),null,true);
 if (public.blog_media_visible('/blog-media/publication-body')->>'visible')::boolean then raise exception 'archived image exposed'; end if;
 if has_function_privilege('anon','public.blog_admin(text,jsonb,text,boolean)','execute') or has_table_privilege('anon','private.blog_articles','select') then raise exception 'public administrative privilege'; end if;
end $$;
select 'blog_publication_unit_passed' as result;
